// Contents: Course animation state for the snowboard: SnowboardMatrixState loads bone matrices,
//   SnowboardCourseAssets owns the per-frame pose tables of a course and copies them, and timed blends
//   between poses use easing curves to build each bone's rotation from its angles.
#include "ff7/snobo_course.h"
#include "ff7/types/snobo.h"
#include "ff7/api/snobo.h"
#include "ff7/snobo_primitives.h"
#include <math.h>

// The bone matrices are three arrays of 20-byte records (retail stride): nine signed 16-bit elements
// read by SnowboardMatrixState::loadMatrices plus a trailing zero alignment word.

struct SnowboardBoneMatrix {
    short m[9];
    short pad;
};

struct SnowboardBoneDefinition {
    short *a, *b, *c;
    short parentA, parentB, length, flag;
};

