    timeLeft -= delta;
    if (timeLeft < 0.0f)
        timeLeft = 0.0f;
    frame.factor = ease((duration - timeLeft) / duration);
    if (frame.factor < 0.0f)
        frame.factor = 0.0f;
    if (frame.factor > 1.0f)
        frame.factor = 1.0f;
